app.post("/folders/:id/share", (req: Request, res) => {
  const userId = (req as AuthenticatedRequest).userId;
  const id = parseId(req.params.id);
  const folder = id === null ? undefined : getFolder(id, userId);

  if (!folder) {
    if (id !== null && isSharedFolderForUser(id, userId)) {
      return res.status(403).json({ error: "Shared folders are read-only" });
    }

    return res.status(404).json({ error: "Folder not found" });
  }

  if (typeof req.body !== "object" || req.body === null || Array.isArray(req.body)) {
    return res.status(400).json({ error: "Request body must be an object" });
  }

  const input = req.body as Record<string, unknown>;
  if (!isValidEmail(input.email)) {
    return res.status(400).json({ error: "email must be valid" });
  }

  const sharedUser = selectUserByEmail.get(input.email.trim().toLowerCase()) as User | undefined;
  if (!sharedUser) {
    return res.status(404).json({ error: "User not found" });
  }

  if (sharedUser.id === userId) {
    return res.status(400).json({ error: "Cannot share a folder with its owner" });
  }

  const existing = getFolderShare(folder.id, sharedUser.id);
  if (existing) {
    return res.status(200).json({ folder_id: folder.id, shared_user: toPublicUser(sharedUser), created_at: existing.created_at });
  }

  const now = new Date().toISOString();
  db.prepare("INSERT INTO folder_shares (folder_id, shared_user_id, created_at) VALUES (?, ?, ?)").run(
    folder.id,
    sharedUser.id,
    now,
  );

  res.status(201).json({ folder_id: folder.id, shared_user: toPublicUser(sharedUser), created_at: now });
});

